"""Summaries over parsed log entries."""

from __future__ import annotations

from collections import Counter


def status_counts(entries: list[dict]) -> dict[int, int]:
    """How many responses had each status code."""
    return dict(sorted(Counter(e["status"] for e in entries).items()))


def top_paths(entries: list[dict], n: int = 3) -> list[tuple[str, int]]:
    """The n most requested paths with their counts, most requested first."""
    return Counter(e["path"] for e in entries).most_common(n)


def error_rate(entries: list[dict]) -> float:
    """Share of responses with a 4xx or 5xx status, rounded to three places."""
    if not entries:
        return 0.0
    return round(sum(e["status"] >= 400 for e in entries) / len(entries), 3)


def summarize(entries: list[dict]) -> dict:
    """All the summaries in one dict."""
    return {
        "requests": len(entries),
        "statuses": status_counts(entries),
        "top_paths": top_paths(entries),
        "bytes": sum(e["size"] for e in entries),
        "error_rate": error_rate(entries),
    }

