from __future__ import annotations

from collections import Counter


def requests_per_hour(entries: list[dict]) -> dict[int, int]:
    """{hour: count} for the hours of day that saw traffic, in order."""
    hours = Counter(int(e["time"].split(":")[1]) for e in entries)
    return dict(sorted(hours.items()))


def render_hours(entries: list[dict]) -> str:
    """One line per hour: two-digit hour, one '#' per request, and the count."""
    counts = requests_per_hour(entries)
    return "\n".join(f"{hour:02d} {'#' * n} {n}" for hour, n in counts.items())

